fmt <- function(x) paste(sprintf("%.17g", x), collapse = ", ")
out <- function(tag, f) { cs <- coef(summary(f)); cat(sprintf("const %s: [f64; 5] = [%s];\n", tag, fmt(c(cs[, 1], cs[, 2], deviance(f))))) }
ctl <- glm.control(epsilon = 1e-15, maxit = 200)
