out("BINOMIAL_PROBIT", glm(Y_BINOMIAL_PROBIT ~ X_BINOMIAL_LOGIT, family = binomial("probit"), control = ctl))
out("BINOMIAL_CLOGLOG", glm(Y_BINOMIAL_CLOGLOG ~ X_BINOMIAL_LOGIT, family = binomial("cloglog"), control = ctl))
nb <- glm.nb(Y_NEGBINOM ~ X_NEGBINOM, control = glm.control(epsilon = 1e-15, maxit = 200)); out("NEGBINOM", nb); cat(sprintf("const NEGBINOM_THETA: f64 = %.17g;\n", nb$theta))
out("GAMMA_LOG", glm(Y_GAMMA_LOG ~ X_GAMMA_LOG, family = Gamma("log"), control = ctl))
out("INVGAUSS_LOG", glm(Y_INVGAUSS_LOG ~ X_INVGAUSS_LOG, family = inverse.gaussian("log"), control = ctl))
out("POISSON_OFFSET", glm(Y_POISSON_OFFSET_R ~ X_POISSON_OFFSET_R + offset(log(EXPOSURE_POISSON_OFFSET_R)), family = poisson, control = ctl))
